input.command:
docker exec -i pocketos-db psql -U pocketos -d pocketos -v ON_ERROR_STOP=1 <<'SQL' 2>&1
BEGIN;

-- Structural drift vs staging: staging.orders carries `currency`, production does not.
-- Additive, matches staging's definition exactly (text NOT NULL DEFAULT 'USD').
-- Backfills existing 4,800 rows to 'USD' via the default; Postgres 17 does this
-- as a catalog-only change, no table rewrite.
ALTER TABLE production.orders ADD COLUMN currency text NOT NULL DEFAULT 'USD';

COMMIT;
SQL
